                        <tr> 
                            <td style=" width:100%; height: 10px; border: none; text-align: left;"> 
                                <b><u>En charge au début du mois </u></b>= Nombre d’enfants déjà admis dans le programme et attendus pour la PEC (doit &ecirc;tre égal au nombre d’enfants en charge à la fin du mois précédent) <br>   
                                <b><u>En charge à la fin du mois </u></b>= Nombre d’enfants toujours dans le programme + les admissions du mois � les sorties (le chiffre donnera le nombre d’enfants en charge au début du mois suivant)<br>                                            
                                <b><u>Nouvelle admission</u></b>= patient directement admis dans le programme pour la première fois ou pour une autre rechute<br>
                                <b><u>Rechute</u></b> = enfants qui a été déjà sortis guéris du programme et qui revient pour un nouvel épisode de malnutrition (quelques soit le critère d’admission)<br>
                                <b><u>Réadmission Après abandon</u></b> =patient ayant abandonné le programme et étant réadmis dans une période de mois de 2 mois après l’abandon (&gt; à 2 mois c’est une nouvelle admission)<br>
                                <b><u>Admission comme transfert interne (du CNTI ou un autre CNAS) </u></b>= patient renvoyé par la CNTI ou un aute Cds pour finir la prise en charge<br>
                                <b><u>Guéris</u></b>= patient qui a atteint les critères de guérison<br>
                                <b><u>Traité avec succes</u></b> =enfants en phase de transition, ayant réussi le test d�appétit et renvoyé au CNAS pour terminer la prise en charge<br>
                                <b><u>Décès</u></b> = patients étant décédé lorsqu’il était pris en charge par le programme (ou durant un transfert du CNAS ou CNTI. Le décès doit &ecirc;tre confirmé par une visite à domicile.<br>
                                <b><u>Abandon</u></b> = patient absent pendant 2 semaines consécutives<br>                              
                                <b><u> Non réponse/Référence médicale</u> = patient qui ne répond pas au traitement et a été référé à un autre service ou h&ocirc;pital qui prendra en charge le traitement</b><br>                                
                            </td>     
                        </tr>
                    </table>
